# 📦 Discount Utility (Core Logic)

This enforces:

- % discounts first  
- Flat discounts second  
- Never below zero  

## 📁 utils/discountCalculator.js

```javascript
function applyDiscounts(cartTotal, coupons) {
  let total = Number(cartTotal);

  // Separate percentage and flat coupons
  const percentageCoupons = coupons.filter(c => c.discount_type === 'PERCENTAGE');
  const flatCoupons = coupons.filter(c => c.discount_type === 'FLAT');

  // 1️⃣ Apply percentage discounts first
  percentageCoupons.forEach(coupon => {
    const discountAmount = (total * coupon.discount_value) / 100;
    total -= discountAmount;
  });

  // 2️⃣ Apply flat discounts second
  flatCoupons.forEach(coupon => {
    total -= coupon.discount_value;
  });

  // 3️⃣ Prevent negative totals
  total = Math.max(0, total);

  return Number(total.toFixed(2));
}

module.exports = applyDiscounts;
```

