# 🎟 Coupon Component

## 📁 components/CouponForm.jsx

```jsx
import React, { useState } from 'react';
import { validateCoupons } from '../services/api';

const CouponForm = ({ cartTotal, userId, onDiscountApplied }) => {
  const [codeInput, setCodeInput] = useState('');
  const [codes, setCodes] = useState([]);
  const [message, setMessage] = useState('');

  const addCoupon = () => {
    if (!codeInput.trim()) return;
    setCodes([...codes, codeInput.trim().toUpperCase()]);
    setCodeInput('');
  };

  const applyCoupons = async () => {
    const data = await validateCoupons({
      userId,
      cartTotal,
      couponCodes: codes
    });

    if (data.finalTotal !== undefined) {
      onDiscountApplied(data.finalTotal);
      setMessage(`Applied: ${data.appliedCoupons.join(', ')}`);
    } else {
      setMessage(data.message);
    }
  };

  return (
    <div>
      <h3>Apply Coupons</h3>

      <input
        value={codeInput}
        onChange={(e) => setCodeInput(e.target.value)}
        placeholder="Enter promo code"
      />
      <button onClick={addCoupon}>Add</button>

      <ul>
        {codes.map((c, i) => (
          <li key={i}>{c}</li>
        ))}
      </ul>

      <button onClick={applyCoupons}>Apply Discounts</button>

      {message && <p>{message}</p>}
    </div>
  );
};

export default CouponForm;
```

